const row=(y,values)=>({y,items:values.map(([x,text])=>({x,text,width:35}))});
function document({type='BILL_OF_LADING',number='SBY2600000000001',containers=2,vessel='TANTO UJI',voyage='165',sender='PENGIRIM QA',recipient='PENERIMA QA',offset=0}={}){
 let rows;
 if(type==='DELIVERY_ORDER')rows=[row(820,[[20,'PT. TANTO INTIM LINE'],[300,'DELIVERY ORDER']]),row(800,[[300,'QKM-26-0001001']]),row(770,[[20,'No. Referensi B/L'],[140,'Kapal/No. Pelayaran'],[300,'Kepada']]),row(750,[[20,number],[140,vessel+' / '+voyage],[300,recipient]]),row(725,[[20,'Pelabuhan Muat'],[140,'Pelabuhan Bongkar'],[300,'Tanggal Kapal Sandar'],[400,'Tanggal Cetak DO'],[500,'DO Berlaku Sampai']]),row(705,[[20,'SURABAYA'],[140,'MERAUKE'],[300,'28-10-2026'],[400,'29-10-2026'],[500,'01-11-2026']])];
 else if(type==='POWER_OF_ATTORNEY')rows=[row(820,[[20,'PT. MITRA QA']]),row(790,[[20,'SURAT KUASA']]),row(770,[[20,'No : 001/QA/X/2026']]),row(740,[[20,'Ex. Kapal : KM. '+vessel+' VOY '+voyage]]),row(720,[[20,'No. B/L : '+number]]),row(700,[[20,'TIBA : 28/ 10/2026']]),row(680,[[20,'Jumlah Kont/Tonase : '+containers+' Kontainer']])];
 else rows=[row(820,[[20,'KONOSEMEN (BILL OF LADING)'],[340,'PT. TANTO INTIM LINE']]),row(795,[[20,vessel+' / '+voyage+' / RELEASED']]),row(760,[[20,'Pengirim']]),row(742,[[20,sender]]),row(720,[[300,'B/L No.'],[420,'Tanggal'],[500,'Jumlah B/L Asli']]),row(702,[[300,number],[420,'02 Oct 2026'],[500,'1 (SATU)']]),row(680,[[20,'Penerima'],[300,'Pelabuhan Muat']]),row(662,[[20,recipient],[300,'SURABAYA']]),row(640,[[300,'Pelabuhan Bongkar']]),row(622,[[300,'MERAUKE']]),row(600,[[20,'Pihak yang Memberitahu']]),row(582,[[20,'SCMU QA']])];
 if(type!=='POWER_OF_ATTORNEY'){rows.push(row(550,[[20,'No.'],[55,'Kontainer'],[145,'Tipe'],[190,'Segel'],[240,'Muatan'],[550,'Berat']]));for(let i=0;i<containers;i++)rows.push(row(530-i*20,[[20,String(i+1)],[55,'TEST '+String(100000+offset+i).padStart(6,'0')+'-'+i%10],[145,"20' ST"],[190,'R90000'+i],[240,'MUATAN QA'],[550,'27.2']]));rows.push(row(60,[[20,'Delivery Order tunduk pada Bill of Lading. Pengirim bertanggung jawab.']]));}
 return {pages:[{number:1,method:'PDF_TEXT',width:600,height:850,rows,text:rows.map(r=>r.items.map(i=>i.text).join(' ')).join('\n')}]};
}
function pdf(doc){const stream=doc.pages[0].rows.flatMap(r=>r.items.map(i=>`BT /F1 9 Tf ${i.x} ${r.y} Td (${i.text.replace(/[\\()]/g,'\\$&')}) Tj ET`)).join('\n'),objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 850] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${Buffer.byteLength(stream)} >>\nstream\n${stream}\nendstream`];let out='%PDF-1.4\n',offsets=[];objects.forEach((obj,i)=>{offsets.push(Buffer.byteLength(out));out+=`${i+1} 0 obj\n${obj}\nendobj\n`;});const offset=Buffer.byteLength(out);out+='xref\n0 6\n0000000000 65535 f \n'+offsets.map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')+`trailer << /Size 6 /Root 1 0 R >>\nstartxref\n${offset}\n%%EOF`;return Buffer.from(out);}
module.exports={document,pdf,row};
